using System;using System.IO;using System.Reflection;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class SignatureClickValidation{
 static SignatureClickValidation(){EditorApplication.delayCall+=Run;}
 static void Run(){var report="D:/-11-scene3-audit/signature-click-validation.txt";if(File.Exists(report))return;if(EditorApplication.isUpdating||EditorApplication.isCompiling){EditorApplication.delayCall+=Run;return;}GameObject go=null;try{go=new GameObject("Temporary signature click test"){hideFlags=HideFlags.HideAndDontSave};var f=go.AddComponent<Scene3SignatureForm>();var type=typeof(Scene3SignatureForm);var flags=BindingFlags.NonPublic|BindingFlags.Instance;var tex=Resources.Load<Texture2D>("Signature/UNIT001Signature");if(!tex)throw new Exception("Signature missing");type.GetField("signature",flags).SetValue(f,tex);type.GetField("document",flags).SetValue(f,tex);var rect=(Rect)type.GetMethod("ConfirmRect",flags).Invoke(f,null);var click=type.GetMethod("HandlePointer",flags);click.Invoke(f,new object[]{new Vector2(-100,-100)});if((bool)type.GetField("signing",flags).GetValue(f))throw new Exception("Outside click triggered signing");click.Invoke(f,new object[]{rect.center});if(!(bool)type.GetField("signing",flags).GetValue(f))throw new Exception("Button click did not start signing");if((float)type.GetField("signElapsed",flags).GetValue(f)!=0)throw new Exception("Animation did not start at zero");File.WriteAllText(report,"PASS: click outside button ignored\nPASS: click inside actual Sign & Confirm rectangle starts UNIT-001 animation\nPASS: signature resource loaded and animation starts at zero\nNo Play Mode start/stop commands used");}catch(Exception e){File.WriteAllText(report,"FAIL: "+e);}finally{if(go)UnityEngine.Object.DestroyImmediate(go);}}
}
